// Location Embargo - client-side mirror of the app's tiered placement embargo.
//
// The Burning Man organization embargoes camp/art placement data until shortly
// before (camps) or at (art) gate opening. Share links generated by an unlocked
// app can carry lat/lng/addr before those dates, so this hides them for anyone
// opening the link early.
//
// This is a courtesy gate, not security: the coordinates are still in the URL.
(function (global) {
    'use strict';

    // Unlock instants per playa year, mirroring iBurn/YearSettings.plist
    // (CampLocationUnlock and EventStart). Adding a year is one line.
    var SCHEDULE = {
        '2026': {
            camp: '2026-08-23T07:01:00Z',
            art: '2026-08-30T07:00:00Z'
        }
    };

    // Links from older app builds may omit ?year=; treat them as the current
    // embargoed year. Any year with no entry above is considered long public.
    var DEFAULT_YEAR = '2026';

    var TIERS = {
        CAMP: 'camp',
        ART: 'art',
        // Never embargoed: user-generated pins.
        UNRESTRICTED: 'unrestricted'
    };

    // Which tier a deeplink page falls into. Events ride their host's tier.
    function tierForPage(type, hostType) {
        if (type === 'pin') {
            return TIERS.UNRESTRICTED;
        }
        if (type === 'art') {
            return TIERS.ART;
        }
        if (type === 'event') {
            return hostType === 'art' ? TIERS.ART : TIERS.CAMP;
        }
        return TIERS.CAMP;
    }

    // Date the tier's locations become public, or null if never embargoed.
    function unlockDate(tier, year) {
        if (tier === TIERS.UNRESTRICTED) {
            return null;
        }
        var schedule = SCHEDULE[String(year || DEFAULT_YEAR)];
        if (!schedule || !schedule[tier]) {
            return null;
        }
        return new Date(schedule[tier]);
    }

    // Pure predicate: may this tier's locations be shown at `now`?
    function canShowLocation(tier, year, now) {
        var unlock = unlockDate(tier, year);
        if (!unlock || isNaN(unlock.getTime())) {
            return true;
        }
        return (now || new Date()).getTime() >= unlock.getTime();
    }

    function formatUnlockDate(date) {
        if (!date) {
            return '';
        }
        return date.toLocaleDateString('en-US', {
            month: 'long',
            day: 'numeric',
            year: 'numeric'
        });
    }

    // Verdict for a page: { allowed, tier, unlockDate, notice }.
    function locationGate(type, hostType, year, now) {
        var tier = tierForPage(type, hostType);
        var allowed = canShowLocation(tier, year, now);
        var unlock = unlockDate(tier, year);
        return {
            tier: tier,
            allowed: allowed,
            unlockDate: unlock,
            notice: allowed ? '' :
                'Location hidden until ' + formatUnlockDate(unlock) +
                " per the Burning Man organization's data embargo."
        };
    }

    var Embargo = {
        TIERS: TIERS,
        tierForPage: tierForPage,
        unlockDate: unlockDate,
        canShowLocation: canShowLocation,
        formatUnlockDate: formatUnlockDate,
        locationGate: locationGate
    };

    global.IBurnEmbargo = Embargo;

    // Allow `node -e` / test harnesses to require this file directly.
    if (typeof module !== 'undefined' && module.exports) {
        module.exports = Embargo;
    }
})(typeof window !== 'undefined' ? window : globalThis);
